```javascript
function findLargerNumber(num1, num2) {
  // Check if both numbers are positive integers
  if (num1 <= 0 || num2 <= 0) {
    throw new Error('Both numbers must be positive integers');
  }

  // Check if the result needs to be rounded
  if (num1 > num2) {
    return Math.max(num1, Math.ceil(num1));
  } else {
